test('throws on negative or too big ID length', () => {
  throws(() => {
    nanoid(2147483648)
  }, /Wrong ID size|Invalid typed array length/)
  throws(() => {
    nanoid(-10)
  }, /Wrong ID size|Invalid typed array length/)
  let a = nanoid()
  let b = nanoid()
  notEqual(a, b)
})

test(`throws on negative size`, () => {
  throws(() => {
    random(-1)
  }, /Wrong ID size|Invalid typed array length/)
})

test(`has flat distribution`, () => {
  let COUNT = 100 * 1000
  let LENGTH = nanoid().length

  let chars = {}
  for (let i = 0; i < COUNT; i++) {
    let id = nanoid()
    for (let char of id) {
      if (!chars[char]) chars[char] = 0
      chars[char] += 1
    }
  }

  equal(Object.keys(chars).length, urlAlphabet.length)

  let max = 0
  let min = Number.MAX_SAFE_INTEGER
  for (let k in chars) {
    let distribution = (chars[k] * urlAlphabet.length) / (COUNT * LENGTH)
    if (distribution > max) max = distribution
    if (distribution < min) min = distribution
  }
  ok(max - min <= 0.05)
})
